import pytest

from bedrock_protocol import v1001, v2168

# generated by gophertunnel b8bd735:
# packet.ResourcePackChunkRequest{UUID: "0575c61f-a5da-4b7f-9961-ffda2908861e_1.0.0", ChunkIndex: 300}
NAMED = bytes.fromhex("2a30353735633631662d613564612d346237662d393936312d6666646132393038383631655f312e302e302c010000")

# generated by gophertunnel b8bd735:
# packet.ResourcePackChunkRequest{UUID: "", ChunkIndex: 0}
EMPTY = bytes.fromhex("0000000000")

# generated by gophertunnel b8bd735:
# packet.ResourcePackChunkRequest{UUID: strings.Repeat("a", 200), ChunkIndex: 7}
LONG_NAME = bytes.fromhex("c801") + bytes.fromhex("61") * 200 + bytes.fromhex("07000000")

GOLDENS = [
    pytest.param(
        v2168.ResourcePackChunkRequestPacket(resource_name="0575c61f-a5da-4b7f-9961-ffda2908861e_1.0.0", chunk=300),
        NAMED,
        id="named",
    ),
    pytest.param(v2168.ResourcePackChunkRequestPacket(resource_name="", chunk=0), EMPTY, id="empty"),
    pytest.param(v2168.ResourcePackChunkRequestPacket(resource_name="a" * 200, chunk=7), LONG_NAME, id="long-name"),
]


@pytest.mark.parametrize("version", [v1001, v2168], ids=lambda version: version.__name__.rpartition(".")[2])
def test_resource_pack_chunk_request_is_packet_84(version):
    assert version.PACKETS[84] is version.ResourcePackChunkRequestPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_resource_pack_chunk_request_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_resource_pack_chunk_request_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet
